from fastapi import FastAPI, Form
from fastapi.responses import HTMLResponse, JSONResponse
from app.planner import make_plan

app = FastAPI(title="Solvent Video Agent")

INDEX = '''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Solvent Video Agent</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui;background:#090b10;color:#f3f5f7}main{max-width:1100px;margin:auto;padding:40px 20px 80px}.brand{font-weight:800;letter-spacing:.04em}.dot{display:inline-block;width:13px;height:13px;border-radius:50%;background:#26e6ff;box-shadow:0 0 28px #26e6ff;margin-right:10px}.hero{padding:55px 0 25px}h1{font-size:clamp(44px,7vw,82px);line-height:.94;letter-spacing:-.06em;margin:0 0 18px}.muted{color:#9298a6;max-width:720px;font-size:18px}.panel{background:linear-gradient(180deg,#11151e,#0d1118);border:1px solid #242a36;border-radius:22px;padding:22px;margin-top:20px}textarea,select{width:100%;background:#090c12;color:white;border:1px solid #2a3240;border-radius:14px;padding:14px;font:inherit}textarea{min-height:140px}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:12px}button{background:#e9fbff;color:#071014;border:0;border-radius:14px;padding:14px 18px;font-weight:800;cursor:pointer}.secondary{background:#161d28;color:#dbe7eb;border:1px solid #2a3443}.scene{border-top:1px solid #252c38;padding:18px 0}.prompt{white-space:pre-wrap;color:#c8d0d8;background:#0a0d13;border-radius:12px;padding:13px;margin:10px 0}.pill{display:inline-block;padding:6px 9px;border:1px solid #2c3744;border-radius:999px;color:#97a8b7;font-size:12px;margin:3px}.status{margin-top:12px;color:#7deaf6}@media(max-width:700px){.row{grid-template-columns:1fr}}</style></head><body><main><div class="brand"><span class="dot"></span>SOLVENT VIDEO AGENT · v1</div><section class="hero"><h1>One idea.<br>One continuous film.</h1><p class="muted">Turn a concept into a cinematic, continuity-aware Reel plan with connected generation prompts.</p></section><div class="panel"><label>What should we create?</label><textarea id="idea">Your UX might not be the problem. Show how deeper business problems become visible through the interface.</textarea><div class="row"><select id="duration"><option value="30">30 seconds</option><option value="45">45 seconds</option><option value="60">60 seconds</option></select><button onclick="generatePlan()">✦ Generate Video Plan</button></div><div id="status" class="status"></div></div><div id="result" class="panel" style="display:none"></div><script>let plan=null;async function generatePlan(){status.textContent='Building continuity map…';const body=new URLSearchParams({idea:idea.value,duration:duration.value});const r=await fetch('/plan',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body});plan=await r.json();let html=`<h2>${plan.title}</h2><p><b>${plan.hook}</b></p><p class="muted">${plan.narration}</p><div>${plan.continuity_rules.map(x=>`<span class="pill">${x}</span>`).join('')}</div>`;for(const s of plan.scenes){html+=`<div class="scene"><h3>Scene ${s.id} · ${s.purpose}</h3><small>${s.duration}s · ${s.camera}</small><div class="prompt" id="p${s.id}">${s.prompt}</div><button class="secondary" onclick="navigator.clipboard.writeText(document.getElementById('p${s.id}').innerText)">Copy prompt</button><p><small>↳ ${s.transition}</small></p></div>`}html+=`<button onclick="downloadManifest()">Export Manifest</button>`;result.innerHTML=html;result.style.display='block';status.textContent='Plan ready.'}function downloadManifest(){const b=new Blob([JSON.stringify(plan,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='solvent-video-manifest.json';a.click()}</script></main></body></html>'''

@app.get("/", response_class=HTMLResponse)
def home():
    return INDEX

@app.post("/plan")
def plan(idea: str = Form(...), duration: int = Form(30)):
    return JSONResponse(make_plan(idea, duration))

@app.get("/health")
def health():
    return {"ok": True, "service": "solvent-video-agent"}
